#!/usr/bin/env ruby
require'json';require'fileutils';root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);files=Dir.glob(File.join(client,'assets/**/*.{prefab,scene}')).sort;parse=[];files.each{|p|begin;JSON.parse(File.read(p));rescue=>e;parse<<{path:p.delete_prefix(client+'/'),error:e.message};end};uuid=JSON.parse(File.read(File.join(root,'work/audit/cocos-uuid-reference-audit.json')));ui=JSON.parse(File.read(File.join(root,'work/audit/ui-backend-closure-audit.json')));report={schemaVersion:1,total:files.length,prefabs:files.count{|p|p.end_with?('.prefab')},scenes:files.count{|p|p.end_with?('.scene')},parseErrors:parse,uuid:uuid['summary'],ui:ui['summary'],creatorOpenSaveEvidence:false,verdict:'awaiting-creator-and-ui-closure'};out=File.join(root,'docs/generated/creal09-prefab-scene.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "CREAL09 AUDITED: #{files.length} serialized assets; editor validation deferred"
